CREATE TABLE mes_model_usage_policy(tenant_id BIGINT PRIMARY KEY,version INT NOT NULL DEFAULT 0,enabled BOOLEAN NOT NULL DEFAULT FALSE,limits_json CLOB,rates_json CLOB,coverage_start TIMESTAMP,updater BIGINT,update_time TIMESTAMP);
CREATE TABLE mes_model_usage_bucket(tenant_id BIGINT NOT NULL,subject_type VARCHAR(10) NOT NULL,subject_id BIGINT NOT NULL,window_type VARCHAR(10) NOT NULL,window_start TIMESTAMP NOT NULL,used_calls BIGINT NOT NULL DEFAULT 0,reserved_calls BIGINT NOT NULL DEFAULT 0,unknown_calls BIGINT NOT NULL DEFAULT 0,known_tokens DECIMAL(38,0) NOT NULL DEFAULT 0,reserved_tokens DECIMAL(38,0) NOT NULL DEFAULT 0,held_unknown_tokens DECIMAL(38,0) NOT NULL DEFAULT 0,unknown_chat_token_calls BIGINT NOT NULL DEFAULT 0,unknown_jev_token_calls BIGINT NOT NULL DEFAULT 0,actual_total_tokens DECIMAL(38,0) NOT NULL DEFAULT 0,calculated_amount DECIMAL(65,8) NOT NULL DEFAULT 0,reserved_amount DECIMAL(65,8) NOT NULL DEFAULT 0,held_unknown_amount DECIMAL(65,8) NOT NULL DEFAULT 0,unpriced_calls BIGINT NOT NULL DEFAULT 0,active_count BIGINT NOT NULL DEFAULT 0,admitted BIGINT NOT NULL DEFAULT 0,version INT NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,subject_type,subject_id,window_type,window_start));
CREATE TABLE mes_model_usage_log(id VARCHAR(36) PRIMARY KEY,tenant_id BIGINT NOT NULL,user_id BIGINT NOT NULL,purpose VARCHAR(40) NOT NULL,channel VARCHAR(10) NOT NULL,status VARCHAR(20) NOT NULL,version INT NOT NULL,state_json CLOB NOT NULL,created_at TIMESTAMP NOT NULL,dispatched_at TIMESTAMP,settled_at TIMESTAMP,stale_after TIMESTAMP);
CREATE INDEX idx_model_usage_owner ON mes_model_usage_log(tenant_id,created_at,id);
CREATE TABLE mes_model_usage_event(id BIGINT AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,request_id VARCHAR(36),event_type VARCHAR(40) NOT NULL,actor_id BIGINT,prior_version INT,new_version INT,reason VARCHAR(1000),state_json CLOB,create_time TIMESTAMP NOT NULL);
